184	// setRootUsage preserves the workflow order without changing Cobra's global
185	// sorting setting or the default help for subcommands.
186	func setRootUsage(root *cobra.Command, commands []*cobra.Command) {
187		defaultUsage := root.UsageFunc()
188		defaultHelp := root.HelpFunc()
189		helpWidth := 0
190		root.SetHelpFunc(func(cmd *cobra.Command, args []string) {
191			// Cobra renders UsageString into a buffer; measure the real output first.
192			if cmd == root {
193				helpWidth = helpTerminalWidth(cmd.OutOrStdout())
194				defer func() { helpWidth = 0 }()
195			}
196			defaultHelp(cmd, args)
197		})
198		root.SetUsageFunc(func(cmd *cobra.Command) error {
199			if cmd != root {
200				return defaultUsage(cmd)
201			}
202			type helpEntry struct {
203				command *cobra.Command
204				name    string
205				group   string
206			}
207			var ordered []helpEntry
208			for _, c := range commands {
209				ordered = append(ordered, helpEntry{c, c.Name(), c.GroupID})
210				if c.Name() == "memories" {
211					// Surface operator paths without moving the everyday memories family
212					// or changing any child's registration or visibility.
213					for _, name := range []string{"import", "sync", "proposals", "gc", "vitality"} {
214						for _, child := range c.Commands() {
215							if child.Name() == name {
216								ordered = append(ordered, helpEntry{child, "memories " + name, "operations"})
217							}
218						}
219					}
220				}
221			}
222			for _, c := range cmd.Commands() {
223				if c.Name() == "help" {
224					ordered = append(ordered, helpEntry{c, c.Name(), c.GroupID})
225				}
226			}
227			var out strings.Builder
228			fmt.Fprintf(&out, "Usage:\n  %s\n  %s [command]\n", cmd.UseLine(), cmd.CommandPath())
229			width := 0
230			for _, entry := range ordered {
231				if !entry.command.Hidden && len(entry.name) > width {
232					width = len(entry.name)
233				}
234			}
235			terminalWidth := helpWidth
236			if terminalWidth == 0 {
237				terminalWidth = helpTerminalWidth(cmd.OutOrStderr())
238			}
239			for _, group := range cmd.Groups() {
240				fmt.Fprintf(&out, "\n%s\n", group.Title)
241				for _, entry := range ordered {
242					c := entry.command
243					if entry.group == group.ID && !c.Hidden && (c.IsAvailableCommand() || c.Name() == "help") {
244						writeHelpCommand(&out, entry.name, c.Short, width, terminalWidth)
245					}
246				}
247			}
248			if all, _ := cmd.Flags().GetBool("help-all"); all {
249				writeAllCommandHelp(&out, cmd, terminalWidth)
250			}
251			fmt.Fprintf(&out, "\nFlags:\n%s", cmd.LocalFlags().FlagUsages())
252			fmt.Fprintf(&out, "\nUse %q for more information about a command.\n", cmd.CommandPath()+" [command] --help")
253			_, err := io.WriteString(cmd.OutOrStderr(), out.String())
254			return err
255		})
256	}
