258	// List full paths without changing Hidden: all-help is an inspection surface,
259	// not a visibility change to the command tree or subsequent help invocations.
260	func writeAllCommandHelp(out io.Writer, root *cobra.Command, terminalWidth int) {
261		var commands []*cobra.Command
262		var paths []string
263		width := 0
264		var collect func(*cobra.Command, string)
265		collect = func(parent *cobra.Command, prefix string) {
266			for _, child := range parent.Commands() {
267				path := prefix + child.Name()
268				commands = append(commands, child)
269				paths = append(paths, path)
270				width = max(width, len(path))
271				collect(child, path+" ")
272			}
273		}
274		collect(root, "")
275		fmt.Fprintln(out, "\nAll commands (including developer and machine commands):")
276		for i, cmd := range commands {
277			writeHelpCommand(out, paths[i], cmd.Short, width, terminalWidth)
278		}
279	}
