281	// Prefer the output terminal. Entire may pipe plugin output, so also consult
282	// the controlling terminal for file-backed output. Unknown width means no wrap.
283	func helpTerminalWidth(out io.Writer) int {
284		if f, ok := out.(interface{ Fd() uintptr }); ok {
285			if width, _, err := term.GetSize(f.Fd()); err == nil && width > 0 {
286				return width
287			}
288			if tty, err := os.Open("/dev/tty"); err == nil {
289				defer tty.Close()
290				if width, _, err := term.GetSize(tty.Fd()); err == nil && width > 0 {
291					return width
292				}
293			}
294		}
295		if width, err := strconv.Atoi(os.Getenv("COLUMNS")); err == nil && width > 0 {
296			return width
297		}
298		return 0
299	}
