301	func writeHelpCommand(out io.Writer, name, description string, nameWidth, terminalWidth int) {
302		indent := nameWidth + 4
303		prefix := fmt.Sprintf("  %-*s  ", nameWidth, name)
304		if terminalWidth <= 0 || ansi.StringWidth(prefix+description) <= terminalWidth {
305			fmt.Fprintln(out, prefix+description)
306			return
307		}
308		// On very narrow terminals, put the description below the command name.
309		if terminalWidth <= indent {
310			fmt.Fprintf(out, "  %s\n", name)
311			indent = min(2, max(0, terminalWidth-1))
312			prefix = strings.Repeat(" ", indent)
313		}
314		wrapped := ansi.Wrap(description, max(1, terminalWidth-indent), "")
315		fmt.Fprintln(out, prefix+strings.ReplaceAll(wrapped, "\n", "\n"+strings.Repeat(" ", indent)))
316	}
