318	type commandJSONError struct {
319		Code    string `json:"code"`
320		Message string `json:"message"`
321	}
322	
323	type renderedCommandError struct {
324		err error
325	}
326	
327	var errRenderedCommand = renderedCommandError{}
328	
329	func RenderedError() error {
330		return errRenderedCommand
331	}
332	
333	func (e renderedCommandError) Error() string {
334		if e.err == nil {
335			return "command error rendered"
336		}
337		return e.err.Error()
338	}
339	
340	func (e renderedCommandError) Unwrap() error {
341		return e.err
342	}
343	
344	func (e renderedCommandError) Is(target error) bool {
345		_, ok := target.(renderedCommandError)
346		return ok
347	}
348	
349	func commandErrorWasRendered(err error) bool {
350		var rendered renderedCommandError
351		return errors.As(err, &rendered)
352	}
353	
354	func wrapJSONErrorRendering(cmd *cobra.Command) {
355		if cmd.Args != nil {
356			argsFunc := cmd.Args
357			cmd.Args = func(cmd *cobra.Command, args []string) error {
358				err := argsFunc(cmd, args)
359				if err == nil || !commandWantsJSONError(cmd) {
360					return err
361				}
362				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
363				return renderedCommandError{err: err}
364			}
365		}
366		if cmd.RunE != nil {
367			run := cmd.RunE
368			cmd.RunE = func(cmd *cobra.Command, args []string) error {
369				err := run(cmd, args)
370				if err == nil || !commandWantsJSONError(cmd) {
371					return err
372				}
373				if commandErrorWasRendered(err) {
374					return err
375				}
376				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
377				return renderedCommandError{err: err}
378			}
379		}
380		// CHAIN, do not replace. This walks every child, and a plain
381		// SetFlagErrorFunc here silently discarded any handler a command had set
382		// for itself -- which is how the `--symbol` hint on `inspect impact`
383		// vanished without a trace: the command set it, this overwrote it, and the
384		// user still saw cobra's bare "unknown flag".
385		//
386		// Any command may now improve its own flag error, and this still gets to
387		// render the JSON form on top.
388		prior := flagErrorFuncOf(cmd)
389		cmd.SetFlagErrorFunc(func(cmd *cobra.Command, err error) error {
390			if prior != nil {
391				err = prior(cmd, err)
392			}
393			if !commandWantsJSONError(cmd) {
394				return err
395			}
396			_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
397			return renderedCommandError{err: err}
398		})
399		for _, child := range cmd.Commands() {
400			wrapJSONErrorRendering(child)
401		}
402	}
403	
404	// flagErrorFuncOf returns a command's OWN flag-error handler, or nil when it
405	// has none.
406	//
407	// cobra's FlagErrorFunc() walks up to the root when a command has not set one,
408	// so calling it directly would return the parent's and chain it to itself.
409	// Comparing against the parent's is what distinguishes "this command set one"
410	// from "this command inherited one".
411	func flagErrorFuncOf(cmd *cobra.Command) func(*cobra.Command, error) error {
412		own := cmd.FlagErrorFunc()
413		if own == nil || cmd.Parent() == nil {
414			return own
415		}
416		inherited := cmd.Parent().FlagErrorFunc()
417		if inherited != nil && reflect.ValueOf(own).Pointer() == reflect.ValueOf(inherited).Pointer() {
418			return nil
419		}
420		return own
421	}
422	
423	func commandWantsJSONError(cmd *cobra.Command) bool {
424		if flag := cmd.Flags().Lookup("format"); flag != nil && flag.Changed {
425			if wants, ok := commandFormatFlagWantsJSON(flag.Value.String()); ok {
426				return wants
427			}
428		}
429		if flag := cmd.InheritedFlags().Lookup("format"); flag != nil && flag.Changed {
430			if wants, ok := commandFormatFlagWantsJSON(flag.Value.String()); ok {
431				return wants
432			}
433		}
434		if wants, ok := commandRawFormatWantsJSON(append(cmd.Flags().Args(), commandRawArgs(cmd)...)); ok {
435			return wants
436		}
437		if flag := cmd.Flags().Lookup("json"); flag != nil && flag.Changed {
438			return commandJSONFlagEnabled(flag.Value.String())
439		}
440		if flag := cmd.InheritedFlags().Lookup("json"); flag != nil && flag.Changed {
441			return commandJSONFlagEnabled(flag.Value.String())
442		}
443		for _, arg := range append(cmd.Flags().Args(), commandRawArgs(cmd)...) {
444			if arg == "--json" {
445				return true
446			}
447			if strings.HasPrefix(arg, "--json=") {
448				value := strings.TrimPrefix(arg, "--json=")
449				return value == "" || value == "true" || value == "1"
450			}
451		}
452		return false
453	}
454	
455	func commandFormatFlagWantsJSON(value string) (bool, bool) {
456		switch strings.ToLower(strings.TrimSpace(value)) {
457		case "json":
458			return true, true
459		case "cli":
460			return false, true
461		default:
462			return false, false
463		}
464	}
465	
466	func commandRawFormatWantsJSON(args []string) (bool, bool) {
467		for i, arg := range args {
468			if arg == "--format" {
469				if i+1 >= len(args) {
470					return false, false
471				}
472				return commandFormatFlagWantsJSON(args[i+1])
473			}
474			if strings.HasPrefix(arg, "--format=") {
475				return commandFormatFlagWantsJSON(strings.TrimPrefix(arg, "--format="))
476			}
477		}
478		return false, false
479	}
480	
481	func commandJSONFlagEnabled(value string) bool {
482		value = strings.ToLower(value)
483		return value != "false" && value != "0"
484	}
485	
486	func commandRawArgs(cmd *cobra.Command) []string {
487		root := cmd.Root()
488		if root == nil {
489			return os.Args[1:]
490		}
491		value := reflect.ValueOf(root)
492		if value.Kind() != reflect.Pointer || value.IsNil() {
493			return os.Args[1:]
494		}
495		args := value.Elem().FieldByName("args")
496		if !args.IsValid() || args.Kind() != reflect.Slice || args.IsNil() {
497			return os.Args[1:]
498		}
499		out := make([]string, 0, args.Len())
500		for i := 0; i < args.Len(); i++ {
501			out = append(out, args.Index(i).String())
502		}
503		return out
504	}
505	
506	var commandErrorCodePattern = regexp.MustCompile(`^[a-z][a-z0-9_-]*$`)
507	
508	func writeCommandJSONError(w io.Writer, err error) error {
509		envelope := commandJSONError{
510			Code:    commandErrorCode(err),
511			Message: err.Error(),
512		}
513		data, marshalErr := json.MarshalIndent(envelope, "", "  ")
514		if marshalErr != nil {
515			return marshalErr
516		}
517		_, writeErr := fmt.Fprintln(w, string(data))
518		return writeErr
519	}
520	
521	func commandErrorCode(err error) string {
522		message := err.Error()
523		code, _, ok := strings.Cut(message, ":")
524		if ok {
525			code = strings.TrimSpace(code)
526			if commandErrorCodePattern.MatchString(code) {
527				return code
528			}
529		}
530		return "command_failed"
531	}
