533	// legacyFlagAlias keeps a renamed flag's old spelling parseable by normalizing
534	// it to the new name. One per flag set: SetNormalizeFunc is single-slot, so a
535	// second call on the same FlagSet replaces the first.
536	func legacyFlagAlias(fs *pflag.FlagSet, oldName, newName string) {
537		fs.SetNormalizeFunc(func(f *pflag.FlagSet, name string) pflag.NormalizedName {
538			if name == oldName {
539				name = newName
540			}
541			return pflag.NormalizedName(name)
542		})
543	}
